import 'server-only';
import {randomUUID} from 'node:crypto';
import {z} from 'zod';
import {database,type Sql} from './db';
import {assertCurrentPrincipal,audit} from './auth';
import {CrmError} from './permissions';
import {commercialDigest as digest,parseCommercial as parse,vietnamBusinessDate} from './commercial-common';
import {fixed,fixedText} from './decimal';
import {sendTransactionalEmail} from './brevo';
import type {Principal} from './types';

const key=z.uuid(),reason=z.string().trim().min(3).max(2000),quantity=z.string().regex(/^\d{1,18}(?:\.\d{1,6})?$/u).refine(v=>fixed(v)>0n),money=z.string().regex(/^(0|[1-9][0-9]{0,29})$/u),day=z.iso.date();
type Supplier={organization_id:string;name:string;code:string;contact_name:string;contact_email:string;contact_phone:string;terms_days:number;payable_enabled:boolean;active:boolean;version:number};
function writer(user:Principal){if(user.area!=='crm'||!['ADMIN','MANAGER','SALES','WAREHOUSE','ACCOUNTANT'].includes(user.role))throw new CrmError('FORBIDDEN',403);}
function manager(user:Principal){if(user.area!=='crm'||!['ADMIN','MANAGER'].includes(user.role))throw new CrmError('FORBIDDEN',403);}
function accountant(user:Principal){if(user.area!=='crm'||!['ADMIN','MANAGER','ACCOUNTANT'].includes(user.role))throw new CrmError('FORBIDDEN',403);}
async function prior(sql:Sql,user:Principal,idempotencyKey:string,h:string){const row=(await sql.query<{request_hash:string;result:unknown}>('SELECT request_hash,result FROM cohamy_crm.procurement_actions WHERE actor_id=$1 AND idempotency_key=$2',[user.id,idempotencyKey])).rows[0];if(!row)return null;if(row.request_hash!==h)throw new CrmError('IDEMPOTENCY_CONFLICT',409);return row.result;}
async function remember(sql:Sql,user:Principal,action:string,id:string,idempotencyKey:string,h:string,result:unknown){await sql.query('INSERT INTO cohamy_crm.procurement_actions(id,action,resource_id,actor_id,idempotency_key,request_hash,result) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)',[randomUUID(),action,id,user.id,idempotencyKey,h,JSON.stringify(result)]);}
async function supplier(sql:Sql,id:string,lock=false){const row=(await sql.query<Supplier>(`SELECT s.*,o.name,o.code FROM cohamy_crm.supplier_profiles s JOIN cohamy_crm.organizations o ON o.id=s.organization_id WHERE s.organization_id=$1 AND o.kind='SUPPLIER'`+(lock?' FOR UPDATE OF s,o':''),[id])).rows[0];if(!row)throw new CrmError('SUPPLIER_NOT_FOUND',404);return row;}
function amountFor(q:string,unit:string){return ((fixed(q)*BigInt(unit)+500000n)/1000000n).toString();}
function dueDate(base:unknown,days:number){const value=base instanceof Date?base.toISOString():String(base),d=new Date(value.slice(0,10)+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}

export async function procurementOverview(user:Principal){if(user.area!=='crm')throw new CrmError('FORBIDDEN',403);const db=await database();const [suppliers,requests,rfqs,orders,receipts,claims,payables,payments]=await Promise.all([
 db.query<Supplier>("SELECT s.*,o.name,o.code FROM cohamy_crm.supplier_profiles s JOIN cohamy_crm.organizations o ON o.id=s.organization_id WHERE o.kind='SUPPLIER' ORDER BY o.name"),
 db.query("SELECT p.*,u.display_name AS requester_name FROM cohamy_crm.purchase_requests p JOIN cohamy_crm.users u ON u.id=p.requester_id ORDER BY p.created_at DESC,p.id LIMIT 200"),
 db.query('SELECT r.*,p.code AS request_code FROM cohamy_crm.supplier_rfqs r JOIN cohamy_crm.purchase_requests p ON p.id=r.request_id ORDER BY r.created_at DESC,r.id LIMIT 200'),
 db.query('SELECT p.*,o.name AS supplier_name FROM cohamy_crm.purchase_orders p JOIN cohamy_crm.organizations o ON o.id=p.supplier_id ORDER BY p.created_at DESC,p.id LIMIT 200'),
 db.query('SELECT g.*,p.code AS order_code,o.name AS supplier_name FROM cohamy_crm.goods_receipts g JOIN cohamy_crm.purchase_orders p ON p.id=g.order_id JOIN cohamy_crm.organizations o ON o.id=p.supplier_id ORDER BY g.received_at DESC,g.id LIMIT 200'),
 db.query('SELECT c.*,p.code AS order_code FROM cohamy_crm.supplier_claims c JOIN cohamy_crm.goods_receipt_lines l ON l.id=c.receipt_line_id JOIN cohamy_crm.goods_receipts g ON g.id=l.receipt_id JOIN cohamy_crm.purchase_orders p ON p.id=g.order_id ORDER BY c.created_at DESC,c.id LIMIT 200'),
 db.query('SELECT p.*,o.name AS supplier_name FROM cohamy_crm.payables p JOIN cohamy_crm.organizations o ON o.id=p.supplier_id ORDER BY p.created_at DESC,p.id LIMIT 200'),
 db.query('SELECT p.*,o.name AS supplier_name FROM cohamy_crm.supplier_payments p JOIN cohamy_crm.organizations o ON o.id=p.supplier_id ORDER BY p.created_at DESC,p.id LIMIT 200'),
 ]);return {suppliers:suppliers.rows,requests:requests.rows,rfqs:rfqs.rows,orders:orders.rows,receipts:receipts.rows,claims:claims.rows,payables:payables.rows,payments:payments.rows};}
export async function procurementOperations(user:Principal){writer(user);const db=await database(),[requestLines,quotes,orderLines,receiptLines,dispatches,amendments]=await Promise.all([db.query('SELECT l.*,p.sku,p.name FROM cohamy_crm.purchase_request_lines l JOIN cohamy_crm.products p ON p.id=l.product_id ORDER BY l.request_id,l.id'),db.query('SELECT q.*,o.name AS supplier_name FROM cohamy_crm.supplier_quotes q JOIN cohamy_crm.organizations o ON o.id=q.supplier_id ORDER BY q.created_at DESC,q.id'),db.query('SELECT l.*,p.sku,p.name FROM cohamy_crm.purchase_order_lines l JOIN cohamy_crm.products p ON p.id=l.product_id ORDER BY l.order_id,l.id'),db.query('SELECT l.*,p.sku FROM cohamy_crm.goods_receipt_lines l JOIN cohamy_crm.purchase_order_lines po ON po.id=l.order_line_id JOIN cohamy_crm.products p ON p.id=po.product_id ORDER BY l.receipt_id,l.id'),db.query('SELECT d.*,o.name AS supplier_name FROM cohamy_crm.supplier_rfq_dispatches d JOIN cohamy_crm.organizations o ON o.id=d.supplier_id ORDER BY d.created_at DESC,d.id'),db.query('SELECT * FROM cohamy_crm.purchase_order_amendments ORDER BY created_at DESC,id')]);return {requestLines:requestLines.rows,quotes:quotes.rows,orderLines:orderLines.rows,receiptLines:receiptLines.rows,dispatches:dispatches.rows,amendments:amendments.rows};}

export async function createSupplier(user:Principal,input:unknown){manager(user);const d=parse(z.object({code:z.string().trim().min(2).max(40).regex(/^[A-Za-z0-9_-]+$/u),name:z.string().trim().min(2).max(200),phone:z.string().trim().max(40),email:z.union([z.literal(''),z.email()]),address:z.string().trim().max(500),businessId:z.string().trim().max(40),contactName:z.string().trim().max(120),termsDays:z.number().int().min(0).max(3650),payableEnabled:z.boolean(),reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const id=randomUUID();await sql.query("INSERT INTO cohamy_crm.organizations(id,code,name,kind,phone,email,address,business_id,contact_name,source,segment,stage) VALUES($1,$2,$3,'SUPPLIER',$4,$5,$6,$7,$8,'PROCUREMENT','SUPPLIER','ACTIVE')",[id,d.code,d.name,d.phone,d.email,d.address,d.businessId,d.contactName]);await sql.query('INSERT INTO cohamy_crm.supplier_profiles(organization_id,contact_name,contact_email,contact_phone,terms_days,payable_enabled) VALUES($1,$2,$3,$4,$5,$6)',[id,d.contactName,d.email,d.phone,d.termsDays,d.payableEnabled]);const result={id,version:1};await remember(sql,user,'SUPPLIER_CREATED',id,d.idempotencyKey,h,result);await audit(sql,user.id,'procurement.supplier-created',id,{after:{code:d.code,name:d.name,termsDays:d.termsDays,payableEnabled:d.payableEnabled},reason:d.reason});return result;});}

export async function saveSupplierProfile(user:Principal,input:unknown){manager(user);const d=parse(z.object({organizationId:z.uuid(),contactName:z.string().trim().max(120),contactEmail:z.union([z.literal(''),z.email()]),contactPhone:z.string().trim().max(40),termsDays:z.number().int().min(0).max(3650),payableEnabled:z.boolean(),active:z.boolean(),version:z.number().int().min(0),reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const org=(await sql.query<{kind:string}>('SELECT kind FROM cohamy_crm.organizations WHERE id=$1 FOR UPDATE',[d.organizationId])).rows[0];if(!org||org.kind!=='SUPPLIER')throw new CrmError('SUPPLIER_ORGANIZATION_REQUIRED',409);const current=(await sql.query<{version:number}>('SELECT version FROM cohamy_crm.supplier_profiles WHERE organization_id=$1 FOR UPDATE',[d.organizationId])).rows[0];if((current?.version??0)!==d.version)throw new CrmError('VERSION_CONFLICT',409);await sql.query('INSERT INTO cohamy_crm.supplier_profiles(organization_id,contact_name,contact_email,contact_phone,terms_days,payable_enabled,active) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(organization_id) DO UPDATE SET contact_name=excluded.contact_name,contact_email=excluded.contact_email,contact_phone=excluded.contact_phone,terms_days=excluded.terms_days,payable_enabled=excluded.payable_enabled,active=excluded.active,version=cohamy_crm.supplier_profiles.version+1,updated_at=now()',[d.organizationId,d.contactName,d.contactEmail,d.contactPhone,d.termsDays,d.payableEnabled,d.active]);const result={organizationId:d.organizationId,version:d.version+1};await remember(sql,user,'SUPPLIER_SAVED',d.organizationId,d.idempotencyKey,h,result);await audit(sql,user.id,'procurement.supplier-saved',d.organizationId,{after:{...d,idempotencyKey:undefined},reason:d.reason});return result;});}
export async function saveSupplierProduct(user:Principal,input:unknown){manager(user);const d=parse(z.object({organizationId:z.uuid(),productId:z.uuid(),supplierSku:z.string().trim().min(1).max(100),leadDays:z.number().int().min(0).max(3650),active:z.boolean(),version:z.number().int().min(0),idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;await supplier(sql,d.organizationId,true);const current=(await sql.query<{version:number}>('SELECT version FROM cohamy_crm.supplier_products WHERE organization_id=$1 AND product_id=$2 FOR UPDATE',[d.organizationId,d.productId])).rows[0];if((current?.version??0)!==d.version)throw new CrmError('VERSION_CONFLICT',409);await sql.query('INSERT INTO cohamy_crm.supplier_products(organization_id,product_id,supplier_sku,lead_days,active) VALUES($1,$2,$3,$4,$5) ON CONFLICT(organization_id,product_id) DO UPDATE SET supplier_sku=excluded.supplier_sku,lead_days=excluded.lead_days,active=excluded.active,version=cohamy_crm.supplier_products.version+1',[d.organizationId,d.productId,d.supplierSku,d.leadDays,d.active]);const result={organizationId:d.organizationId,productId:d.productId,version:d.version+1};await remember(sql,user,'SUPPLIER_PRODUCT_SAVED',d.organizationId+':'+d.productId,d.idempotencyKey,h,result);return result;});}

export async function createPurchaseRequest(user:Principal,input:unknown){writer(user);const d=parse(z.object({neededOn:day,lines:z.array(z.object({productId:z.uuid(),quantity,note:z.string().trim().max(500)}).strict()).min(1).max(200),reason,idempotencyKey:key}).strict(),input),h=digest(d);if(new Set(d.lines.map(l=>l.productId)).size!==d.lines.length)throw new CrmError('DUPLICATE_PRODUCT',400);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const found=(await sql.query<{n:string}>('SELECT count(*)::text AS n FROM cohamy_crm.products WHERE id=ANY($1::uuid[]) AND active',[d.lines.map(l=>l.productId)])).rows[0];if(Number(found.n)!==d.lines.length)throw new CrmError('PRODUCT_NOT_FOUND',404);const id=randomUUID(),code=`DNM-${vietnamBusinessDate(new Date())}-${id.slice(0,8).toUpperCase()}`,result={id,code,status:'REQUESTED',version:1};await sql.query("INSERT INTO cohamy_crm.purchase_requests(id,code,status,needed_on,requester_id,reason) VALUES($1,$2,'REQUESTED',$3,$4,$5)",[id,code,d.neededOn,user.id,d.reason]);for(const line of d.lines)await sql.query('INSERT INTO cohamy_crm.purchase_request_lines(id,request_id,product_id,quantity,note) VALUES($1,$2,$3,$4,$5)',[randomUUID(),id,line.productId,line.quantity,line.note]);await sql.query("INSERT INTO cohamy_crm.purchase_request_events(id,request_id,action,payload,actor_id,reason,idempotency_key,request_hash,result) VALUES($1,$2,'REQUESTED',$3::jsonb,$4,$5,$6,$7,$8::jsonb)",[randomUUID(),id,JSON.stringify({neededOn:d.neededOn,lines:d.lines}),user.id,d.reason,d.idempotencyKey,h,JSON.stringify(result)]);await remember(sql,user,'PURCHASE_REQUESTED',id,d.idempotencyKey,h,result);return result;});}
export async function decidePurchaseRequest(user:Principal,input:unknown){manager(user);const d=parse(z.object({id:z.uuid(),version:z.number().int().positive(),decision:z.enum(['APPROVE','REJECT']),reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const row=(await sql.query<{id:string;status:string;version:number;requester_id:string}>('SELECT id,status,version,requester_id FROM cohamy_crm.purchase_requests WHERE id=$1 FOR UPDATE',[d.id])).rows[0];if(!row||row.version!==d.version||row.status!=='REQUESTED')throw new CrmError('VERSION_CONFLICT',409);if(row.requester_id===user.id)throw new CrmError('SELF_APPROVAL_BLOCKED',403);const status=d.decision==='APPROVE'?'APPROVED':'REJECTED',result={id:row.id,status,version:row.version+1};await sql.query('UPDATE cohamy_crm.purchase_requests SET status=$1,approver_id=$2,version=version+1,updated_at=now() WHERE id=$3',[status,user.id,row.id]);await sql.query('INSERT INTO cohamy_crm.purchase_request_events(id,request_id,action,payload,actor_id,reason,idempotency_key,request_hash,result) VALUES($1,$2,$3,$4::jsonb,$5,$6,$7,$8,$9::jsonb)',[randomUUID(),row.id,d.decision,JSON.stringify({before:row.status,after:status}),user.id,d.reason,d.idempotencyKey,h,JSON.stringify(result)]);await remember(sql,user,'PURCHASE_REQUEST_'+d.decision,row.id,d.idempotencyKey,h,result);return result;});}

export async function createRfq(user:Principal,input:unknown){writer(user);const d=parse(z.object({requestId:z.uuid(),deadline:z.iso.datetime({offset:true}),supplierIds:z.array(z.uuid()).min(1).max(100),reason,idempotencyKey:key}).strict(),input),h=digest(d);if(new Set(d.supplierIds).size!==d.supplierIds.length)throw new CrmError('DUPLICATE_SUPPLIER',400);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const request=(await sql.query<{id:string;code:string;status:string;needed_on:string}>('SELECT id,code,status,needed_on::text FROM cohamy_crm.purchase_requests WHERE id=$1 FOR UPDATE',[d.requestId])).rows[0];if(!request||request.status!=='APPROVED')throw new CrmError('PURCHASE_REQUEST_NOT_APPROVED',409);for(const id of d.supplierIds){const s=await supplier(sql,id);if(!s.active)throw new CrmError('SUPPLIER_INACTIVE',409);}const lines=(await sql.query<{id:string;product_id:string;quantity:string;note:string}>('SELECT id,product_id,quantity::text,note FROM cohamy_crm.purchase_request_lines WHERE request_id=$1 ORDER BY id',[request.id])).rows,snapshot={requestId:request.id,neededOn:String(request.needed_on).slice(0,10),deadline:d.deadline,supplierIds:d.supplierIds,lines},id=randomUUID(),versionId=randomUUID(),code=`RFQ-${vietnamBusinessDate(new Date())}-${id.slice(0,8).toUpperCase()}`,result={id,code,version:1,status:'OPEN'};await sql.query("INSERT INTO cohamy_crm.supplier_rfqs(id,code,request_id,status,deadline,actor_id) VALUES($1,$2,$3,'OPEN',$4,$5)",[id,code,request.id,d.deadline,user.id]);await sql.query('INSERT INTO cohamy_crm.supplier_rfq_versions(id,rfq_id,number,snapshot,checksum,actor_id) VALUES($1,$2,1,$3::jsonb,$4,$5)',[versionId,id,JSON.stringify(snapshot),digest(snapshot),user.id]);await remember(sql,user,'RFQ_CREATED',id,d.idempotencyKey,h,result);return result;});}
export async function dispatchRfq(user:Principal,input:unknown){writer(user);const d=parse(z.object({rfqId:z.uuid(),supplierId:z.uuid(),channel:z.enum(['INTERNAL','EMAIL']),recipient:z.string().trim().min(1).max(320),reason,idempotencyKey:key}).strict(),input),h=digest(d);const db=await database();const prepared=await db.transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return {old};const rfq=(await sql.query<{id:string;code:string;status:string;deadline:string}>('SELECT id,code,status,deadline FROM cohamy_crm.supplier_rfqs WHERE id=$1 FOR UPDATE',[d.rfqId])).rows[0];if(!rfq||rfq.status!=='OPEN')throw new CrmError('RFQ_NOT_OPEN',409);const profile=await supplier(sql,d.supplierId),version=(await sql.query<{number:number;snapshot:{supplierIds:string[];lines:{id:string;product_id:string;quantity:string;note:string}[];neededOn:string};checksum:string}>('SELECT number,snapshot,checksum FROM cohamy_crm.supplier_rfq_versions WHERE rfq_id=$1 ORDER BY number DESC LIMIT 1',[rfq.id])).rows[0];if(!version.snapshot.supplierIds.includes(d.supplierId)||version.checksum!==digest(version.snapshot))throw new CrmError('RFQ_SUPPLIER_INVALID',409);if(d.channel==='EMAIL'&&(d.recipient!==profile.contact_email||!z.email().safeParse(d.recipient).success))throw new CrmError('RFQ_RECIPIENT_INVALID',400);if(d.channel==='INTERNAL'&&d.recipient!==d.supplierId)throw new CrmError('RFQ_RECIPIENT_INVALID',400);const products=(await sql.query<{id:string;sku:string;name:string}>('SELECT id,sku,name FROM cohamy_crm.products WHERE id=ANY($1::uuid[])',[version.snapshot.lines.map(l=>l.product_id)])).rows,lookup=new Map(products.map(p=>[p.id,p])),content={rfqId:rfq.id,code:rfq.code,version:version.number,checksum:version.checksum,deadline:rfq.deadline,neededOn:version.snapshot.neededOn,lines:version.snapshot.lines.map(l=>({...l,sku:lookup.get(l.product_id)?.sku,name:lookup.get(l.product_id)?.name}))};return {rfq,content};});if('old' in prepared)return prepared.old;let providerKey:string|undefined;if(d.channel==='EMAIL'){const lines=prepared.content.lines.map(l=>`${l.sku} · ${l.name} · ${l.quantity}`).join('\n');providerKey=await sendTransactionalEmail(d.recipient,`Yêu cầu báo giá ${prepared.rfq.code}`,`Hạn phản hồi: ${prepared.rfq.deadline}\nNgày cần: ${prepared.content.neededOn}\n${lines}\n\n${d.reason}`,d.idempotencyKey);}return db.transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const id=randomUUID(),status=d.channel==='EMAIL'?'SENT':'RECORDED',result={id,rfqId:d.rfqId,supplierId:d.supplierId,channel:d.channel,status,providerKey:providerKey??null};await sql.query('INSERT INTO cohamy_crm.supplier_rfq_dispatches(id,rfq_id,supplier_id,channel,recipient,content_snapshot,status,provider_key,actor_id,reason,idempotency_key,request_hash) VALUES($1,$2,$3,$4,$5,$6::jsonb,$7,$8,$9,$10,$11,$12)',[id,d.rfqId,d.supplierId,d.channel,d.recipient,JSON.stringify(prepared.content),status,providerKey??null,user.id,d.reason,d.idempotencyKey,h]);await remember(sql,user,'RFQ_DISPATCHED',id,d.idempotencyKey,h,result);await audit(sql,user.id,'procurement.rfq-dispatched',id,{after:result,reason:d.reason});return result;});}
export async function addSupplierQuote(user:Principal,input:unknown){writer(user);const line=z.object({requestLineId:z.uuid(),quantity,unitPrice:money,expectedOn:day,feeAmount:money}).strict(),d=parse(z.object({rfqId:z.uuid(),supplierId:z.uuid(),lines:z.array(line).min(1).max(200),terms:z.string().trim().min(1).max(2000),validUntil:day,reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const rfq=(await sql.query<{id:string;status:string;deadline:string}>('SELECT id,status,deadline FROM cohamy_crm.supplier_rfqs WHERE id=$1 FOR UPDATE',[d.rfqId])).rows[0];if(!rfq||rfq.status!=='OPEN')throw new CrmError('RFQ_NOT_OPEN',409);await supplier(sql,d.supplierId);const version=(await sql.query<{snapshot:{supplierIds:string[];lines:{id:string;product_id:string;quantity:string}[]};checksum:string}>('SELECT snapshot,checksum FROM cohamy_crm.supplier_rfq_versions WHERE rfq_id=$1 ORDER BY number DESC LIMIT 1',[rfq.id])).rows[0];if(version.checksum!==digest(version.snapshot)||!version.snapshot.supplierIds.includes(d.supplierId))throw new CrmError('RFQ_SUPPLIER_INVALID',409);const allowed=new Map(version.snapshot.lines.map(l=>[l.id,l]));let total=0n;for(const l of d.lines){const source=allowed.get(l.requestLineId);if(!source||fixed(l.quantity)>fixed(source.quantity))throw new CrmError('SUPPLIER_QUOTE_LINE_INVALID',409);total+=BigInt(amountFor(l.quantity,l.unitPrice))+BigInt(l.feeAmount);}const number=Number((await sql.query<{n:number}>('SELECT COALESCE(max(number),0)+1 AS n FROM cohamy_crm.supplier_quotes WHERE rfq_id=$1 AND supplier_id=$2',[rfq.id,d.supplierId])).rows[0].n),snapshot={supplierId:d.supplierId,rfqVersionChecksum:version.checksum,lines:d.lines,terms:d.terms,validUntil:d.validUntil,totalAmount:total.toString(),currency:'VND'},id=randomUUID(),result={id,number,totalAmount:total.toString(),status:'RECEIVED'};await sql.query('INSERT INTO cohamy_crm.supplier_quotes(id,rfq_id,supplier_id,number,snapshot,checksum,actor_id) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7)',[id,rfq.id,d.supplierId,number,JSON.stringify(snapshot),digest(snapshot),user.id]);await remember(sql,user,'SUPPLIER_QUOTE_ADDED',id,d.idempotencyKey,h,result);return result;});}
export async function compareRfq(user:Principal,id:string){writer(user);parse(z.uuid(),id);const rows=(await(await database()).query<{id:string;supplier_id:string;supplier_name:string;number:number;snapshot:{totalAmount:string;validUntil:string;terms:string;lines:{expectedOn:string}[]};status:string}>('SELECT q.id,q.supplier_id,o.name AS supplier_name,q.number,q.snapshot,q.status FROM cohamy_crm.supplier_quotes q JOIN cohamy_crm.organizations o ON o.id=q.supplier_id WHERE q.rfq_id=$1 ORDER BY (q.snapshot->>\'totalAmount\')::numeric,q.created_at,q.id',[id])).rows;return rows.map(r=>({...r,comparisonBasis:{currency:'VND',baseQuantity:true,totalAmount:r.snapshot.totalAmount,latestExpectedOn:r.snapshot.lines.map(l=>l.expectedOn).sort().at(-1),validUntil:r.snapshot.validUntil,terms:r.snapshot.terms}}));}
