export async function createSupplierClaim(user:Principal,input:unknown){writer(user);const d=parse(z.object({receiptLineId:z.uuid(),quantity,reason,documentVersionId:z.uuid().nullable(),idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const line=(await sql.query<{rejected:string}>('SELECT rejected::text FROM cohamy_crm.goods_receipt_lines WHERE id=$1',[d.receiptLineId])).rows[0];if(!line||fixed(d.quantity)>fixed(line.rejected))throw new CrmError('CLAIM_EXCEEDS_REJECTED',409);const claimed=(await sql.query<{q:string}>('SELECT COALESCE(sum(quantity),0)::text AS q FROM cohamy_crm.supplier_claims WHERE receipt_line_id=$1 AND status<>\'REJECTED\'',[d.receiptLineId])).rows[0];if(fixed(claimed.q)+fixed(d.quantity)>fixed(line.rejected))throw new CrmError('CLAIM_EXCEEDS_REJECTED',409);const id=randomUUID(),code=`KNCC-${vietnamBusinessDate(new Date())}-${id.slice(0,8).toUpperCase()}`,result={id,code,status:'OPEN',version:1};await sql.query("INSERT INTO cohamy_crm.supplier_claims(id,code,receipt_line_id,quantity,reason,status,document_version_id,actor_id) VALUES($1,$2,$3,$4,$5,'OPEN',$6,$7)",[id,code,d.receiptLineId,d.quantity,d.reason,d.documentVersionId,user.id]);await sql.query("INSERT INTO cohamy_crm.supplier_claim_events(id,claim_id,action,payload,actor_id,reason,idempotency_key,request_hash,result) VALUES($1,$2,'OPENED',$3::jsonb,$4,$5,$6,$7,$8::jsonb)",[randomUUID(),id,JSON.stringify({quantity:d.quantity,documentVersionId:d.documentVersionId}),user.id,d.reason,d.idempotencyKey,h,JSON.stringify(result)]);await remember(sql,user,'SUPPLIER_CLAIM_OPENED',id,d.idempotencyKey,h,result);return result;});}
export async function updateSupplierClaim(user:Principal,input:unknown){writer(user);const d=parse(z.object({id:z.uuid(),version:z.number().int().positive(),status:z.enum(['ACKNOWLEDGED','RESOLVED','REJECTED']),reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const row=(await sql.query<{id:string;version:number;status:string}>('SELECT id,version,status FROM cohamy_crm.supplier_claims WHERE id=$1 FOR UPDATE',[d.id])).rows[0];if(!row||row.version!==d.version||!['OPEN','ACKNOWLEDGED'].includes(row.status))throw new CrmError('VERSION_CONFLICT',409);const result={id:row.id,status:d.status,version:row.version+1};await sql.query('UPDATE cohamy_crm.supplier_claims SET status=$1,version=version+1,updated_at=now() WHERE id=$2',[d.status,row.id]);await sql.query('INSERT INTO cohamy_crm.supplier_claim_events(id,claim_id,action,payload,actor_id,reason,idempotency_key,request_hash,result) VALUES($1,$2,$3,$4::jsonb,$5,$6,$7,$8,$9::jsonb)',[randomUUID(),row.id,d.status,JSON.stringify({before:row.status,after:d.status}),user.id,d.reason,d.idempotencyKey,h,JSON.stringify(result)]);await remember(sql,user,'SUPPLIER_CLAIM_'+d.status,row.id,d.idempotencyKey,h,result);return result;});}

export async function postPayable(user:Principal,input:unknown){accountant(user);const d=parse(z.object({receiptId:z.uuid(),reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const receipt=(await sql.query<{id:string;order_id:string;supplier_id:string;received_at:string;terms_snapshot:{termsDays:number}}>('SELECT g.id,g.order_id,p.supplier_id,g.received_at,p.terms_snapshot FROM cohamy_crm.goods_receipts g JOIN cohamy_crm.purchase_orders p ON p.id=g.order_id WHERE g.id=$1 FOR UPDATE OF g,p',[d.receiptId])).rows[0];if(!receipt)throw new CrmError('NOT_FOUND',404);const profile=await supplier(sql,receipt.supplier_id,true);if(!profile.payable_enabled)throw new CrmError('PAYABLE_POLICY_DISABLED',409);const total=(await sql.query<{amount:string}>(`SELECT COALESCE(sum(round(l.accepted*po.unit_price)),0)::text AS amount FROM cohamy_crm.goods_receipt_lines l JOIN cohamy_crm.purchase_order_lines po ON po.id=l.order_line_id WHERE l.receipt_id=$1`,[receipt.id])).rows[0].amount;if(BigInt(total)<=0n)throw new CrmError('PAYABLE_ZERO',409);const id=randomUUID(),code=`PTT-${vietnamBusinessDate(new Date(receipt.received_at))}-${id.slice(0,8).toUpperCase()}`,terms={days:profile.terms_days,supplierProfileVersion:profile.version,receiptId:receipt.id,receivedAt:new Date(receipt.received_at).toISOString()},result={id,code,amount:total,dueOn:dueDate(receipt.received_at,profile.terms_days),status:'OPEN',version:1};await sql.query("INSERT INTO cohamy_crm.payables(id,code,supplier_id,receipt_id,original_amount,remaining_amount,due_on,terms_snapshot,status) VALUES($1,$2,$3,$4,$5,$5,$6,$7::jsonb,'OPEN')",[id,code,receipt.supplier_id,receipt.id,total,result.dueOn,JSON.stringify(terms)]);await sql.query("INSERT INTO cohamy_crm.payable_events(id,payable_id,action,amount,payload,actor_id,reason,idempotency_key,request_hash,result) VALUES($1,$2,'POSTED',$3,$4::jsonb,$5,$6,$7,$8,$9::jsonb)",[randomUUID(),id,total,JSON.stringify({receiptId:receipt.id,terms}),user.id,d.reason,d.idempotencyKey,h,JSON.stringify(result)]);await remember(sql,user,'PAYABLE_POSTED',id,d.idempotencyKey,h,result);return result;});}
export async function createSupplierPayment(user:Principal,input:unknown){accountant(user);const d=parse(z.object({supplierId:z.uuid(),amount:z.string().regex(/^[1-9][0-9]{0,29}$/u),reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;await supplier(sql,d.supplierId,true);const id=randomUUID(),code=`CNCC-${vietnamBusinessDate(new Date())}-${id.slice(0,8).toUpperCase()}`,result={id,code,status:'PENDING',version:1};await sql.query("INSERT INTO cohamy_crm.supplier_payments(id,code,supplier_id,amount,status,requester_id) VALUES($1,$2,$3,$4,'PENDING',$5)",[id,code,d.supplierId,d.amount,user.id]);await remember(sql,user,'SUPPLIER_PAYMENT_CREATED',id,d.idempotencyKey,h,result);return result;});}
export async function actSupplierPayment(user:Principal,input:unknown){accountant(user);const allocation=z.object({payableId:z.uuid(),amount:z.string().regex(/^[1-9][0-9]{0,29}$/u)}).strict(),d=parse(z.object({id:z.uuid(),version:z.number().int().positive(),action:z.enum(['APPROVE','EXECUTE','REVERSE']),allocations:z.array(allocation).max(200).default([]),reason,idempotencyKey:key}).strict(),input),h=digest(d);return(await database()).transaction(async sql=>{await assertCurrentPrincipal(sql,user);const old=await prior(sql,user,d.idempotencyKey,h);if(old)return old;const payment=(await sql.query<{id:string;supplier_id:string;amount:string;allocated_amount:string;status:string;version:number;requester_id:string}>('SELECT id,supplier_id,amount::text,allocated_amount::text,status,version,requester_id FROM cohamy_crm.supplier_payments WHERE id=$1 FOR UPDATE',[d.id])).rows[0];if(!payment||payment.version!==d.version)throw new CrmError('VERSION_CONFLICT',409);let status=payment.status;if(d.action==='APPROVE'){manager(user);if(payment.status!=='PENDING'||payment.requester_id===user.id)throw new CrmError(payment.requester_id===user.id?'SELF_APPROVAL_BLOCKED':'PAYMENT_STATE_INVALID',409);status='APPROVED';await sql.query("UPDATE cohamy_crm.supplier_payments SET status='APPROVED',approver_id=$1,version=version+1,updated_at=now() WHERE id=$2",[user.id,payment.id]);}else if(d.action==='EXECUTE'){if(payment.status!=='APPROVED'||!d.allocations.length)throw new CrmError('PAYMENT_STATE_INVALID',409);if(new Set(d.allocations.map(a=>a.payableId)).size!==d.allocations.length)throw new CrmError('DUPLICATE_PAYABLE',400);let total=0n;for(const a of [...d.allocations].sort((x,y)=>x.payableId.localeCompare(y.payableId))){const p=(await sql.query<{id:string;supplier_id:string;remaining_amount:string;status:string}>('SELECT id,supplier_id,remaining_amount::text,status FROM cohamy_crm.payables WHERE id=$1 FOR UPDATE',[a.payableId])).rows[0];if(!p||p.supplier_id!==payment.supplier_id||!['OPEN','PARTIAL','DISPUTED'].includes(p.status)||BigInt(a.amount)>BigInt(p.remaining_amount))throw new CrmError('PAYABLE_ALLOCATION_INVALID',409);const remain=BigInt(p.remaining_amount)-BigInt(a.amount);total+=BigInt(a.amount);await sql.query('UPDATE cohamy_crm.payables SET remaining_amount=$1,status=$2,version=version+1,updated_at=now() WHERE id=$3',[remain.toString(),remain===0n?'PAID':'PARTIAL',p.id]);await sql.query('INSERT INTO cohamy_crm.supplier_payment_allocations(id,payment_id,payable_id,amount,actor_id,reason) VALUES($1,$2,$3,$4,$5,$6)',[randomUUID(),payment.id,p.id,a.amount,user.id,d.reason]);await sql.query("INSERT INTO cohamy_crm.payable_events(id,payable_id,action,amount,payload,actor_id,reason,idempotency_key,request_hash,result) VALUES($1,$2,'PAYMENT_APPLIED',$3,$4::jsonb,$5,$6,$7,$8,$9::jsonb)",[randomUUID(),p.id,a.amount,JSON.stringify({paymentId:payment.id}),user.id,d.reason,randomUUID(),h,JSON.stringify({remaining:remain.toString()})]);}if(BigInt(payment.allocated_amount)+total>BigInt(payment.amount))throw new CrmError('PAYMENT_OVERALLOCATED',409);status='EXECUTED';await sql.query("UPDATE cohamy_crm.supplier_payments SET status='EXECUTED',allocated_amount=allocated_amount+$1,version=version+1,updated_at=now() WHERE id=$2",[total.toString(),payment.id]);}else{manager(user);if(payment.status!=='EXECUTED')throw new CrmError('PAYMENT_STATE_INVALID',409);status='REVERSED';const allocations=(await sql.query<{payable_id:string;amount:string}>('SELECT payable_id,amount::text FROM cohamy_crm.supplier_payment_allocations WHERE payment_id=$1 ORDER BY payable_id FOR SHARE',[payment.id])).rows;for(const a of allocations){const p=(await sql.query<{remaining_amount:string;original_amount:string}>('SELECT remaining_amount::text,original_amount::text FROM cohamy_crm.payables WHERE id=$1 FOR UPDATE',[a.payable_id])).rows[0],remain=BigInt(p.remaining_amount)+BigInt(a.amount);if(remain>BigInt(p.original_amount))throw new CrmError('PAYABLE_BALANCE_INVALID',503);await sql.query('UPDATE cohamy_crm.payables SET remaining_amount=$1,status=CASE WHEN $1::numeric=original_amount THEN \'OPEN\' ELSE \'PARTIAL\' END,version=version+1,updated_at=now() WHERE id=$2',[remain.toString(),a.payable_id]);await sql.query("INSERT INTO cohamy_crm.payable_events(id,payable_id,action,amount,payload,actor_id,reason,idempotency_key,request_hash,result) VALUES($1,$2,'PAYMENT_REVERSED',$3,$4::jsonb,$5,$6,$7,$8,$9::jsonb)",[randomUUID(),a.payable_id,'-'+a.amount,JSON.stringify({paymentId:payment.id}),user.id,d.reason,randomUUID(),h,JSON.stringify({remaining:remain.toString()})]);}await sql.query("UPDATE cohamy_crm.supplier_payments SET status='REVERSED',version=version+1,updated_at=now() WHERE id=$1",[payment.id]);}const result={id:payment.id,status,version:payment.version+1};await remember(sql,user,'SUPPLIER_PAYMENT_'+d.action,payment.id,d.idempotencyKey,h,result);return result;});}

export async function supplierPerformance(user:Principal,input?:{from:string;to:string}){writer(user);const db=await database(),bounds=input??(await db.query<{from:string;to:string}>("SELECT (current_date-365)::text AS \"from\",current_date::text AS \"to\"")).rows[0],d=parse(z.object({from:day,to:day}).strict(),bounds);if(d.from>d.to)throw new CrmError('INVALID_FIELDS',400);return(await db.query<{supplier_id:string;supplier_name:string;orders:string;receipts:string;ordered:string;accepted:string;rejected:string;on_time:string}>(`WITH ordered AS(SELECT p.id,p.supplier_id,p.expected_on,sum(l.quantity) AS ordered FROM cohamy_crm.purchase_orders p JOIN cohamy_crm.purchase_order_lines l ON l.order_id=p.id WHERE p.created_at::date<=$2 GROUP BY p.id,p.supplier_id,p.expected_on),received AS(SELECT g.order_id,count(DISTINCT g.id) AS receipts,count(DISTINCT g.id) FILTER(WHERE g.received_at::date<=p.expected_on) AS on_time,COALESCE(sum(gl.accepted),0) AS accepted,COALESCE(sum(gl.rejected),0) AS rejected FROM cohamy_crm.goods_receipts g JOIN cohamy_crm.purchase_orders p ON p.id=g.order_id JOIN cohamy_crm.goods_receipt_lines gl ON gl.receipt_id=g.id WHERE g.received_at::date BETWEEN $1 AND $2 GROUP BY g.order_id) SELECT x.supplier_id,o.name AS supplier_name,count(x.id)::text AS orders,COALESCE(sum(r.receipts),0)::text AS receipts,COALESCE(sum(x.ordered),0)::text AS ordered,COALESCE(sum(r.accepted),0)::text AS accepted,COALESCE(sum(r.rejected),0)::text AS rejected,COALESCE(sum(r.on_time),0)::text AS on_time FROM ordered x JOIN cohamy_crm.organizations o ON o.id=x.supplier_id LEFT JOIN received r ON r.order_id=x.id GROUP BY x.supplier_id,o.name ORDER BY o.name`,[d.from,d.to])).rows;}
